export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function findLessons(catalog,filter={}){return catalog.filter(l=>(filter.grade==null||l.grade===Number(filter.grade))&&(!filter.subject||l.subject===filter.subject)&&(filter.week==null||l.week===Number(filter.week))&&(filter.day==null||filter.day===''||l.day===Number(filter.day))).sort((a,b)=>a.week-b.week||a.day-b.day||a.lessonOrder-b.lessonOrder);}
export const getLesson=(catalog,id)=>catalog.find(l=>l.id===id);
export function groupTopics(lessons){const topics=new Map();for(const l of lessons){if(!topics.has(l.topic))topics.set(l.topic,{title:l.topic,order:l.topicOrder,subtopics:new Map()});const topic=topics.get(l.topic);if(!topic.subtopics.has(l.subtopic))topic.subtopics.set(l.subtopic,{title:l.subtopic,order:l.subtopicOrder,lessons:[]});topic.subtopics.get(l.subtopic).lessons.push(l);}return [...topics.values()].sort((a,b)=>a.order-b.order).map(t=>({...t,subtopics:[...t.subtopics.values()].sort((a,b)=>a.order-b.order)}));}
export function neighbours(catalog,id){const lesson=getLesson(catalog,id);if(!lesson)return {previous:null,next:null};const list=findLessons(catalog,{grade:lesson.grade,subject:lesson.subject});const i=list.findIndex(l=>l.id===id);return {previous:list[i-1]??null,next:list[i+1]??null};}
export function parseRoute(hash){const parts=hash.replace(/^#\/?/,'').split('/');if(parts[0]==='help')return {screen:'help'};if(parts[0]==='saved')return {screen:'saved'};if(parts[0]==='lesson'){let id;try{id=decodeURIComponent(parts[1]||'');}catch{id='';}return {screen:'lesson',id,view:parts[2]==='teach'?'teach':'prepare',step:Math.max(0,Number.parseInt(parts[3]||'0',10)||0)};}return {screen:'find'};}
export function createStore(storage){const memory=new Map();let failed=!storage;return {get available(){return !failed;},get(key,fallback){try{const raw=storage?.getItem(key)??memory.get(key);if(raw==null)return fallback;return JSON.parse(raw);}catch{failed=true;try{return memory.has(key)?JSON.parse(memory.get(key)):fallback;}catch{return fallback;}}},set(key,value){memory.set(key,JSON.stringify(value));try{if(!storage)throw new Error('No storage');storage.setItem(key,JSON.stringify(value));return true;}catch{failed=true;return false;}}};}
export function validateCatalog(catalog){const errors=[];const ids=new Set(),mappings=new Set();for(const l of catalog){const ref=l.id||'unnamed lesson';if(ids.has(l.id))errors.push(`${ref}: duplicate id`);ids.add(l.id);for(const f of ['id','subject','topic','subtopic','title','outcome'])if(!l[f])errors.push(`${ref}: missing ${f}`);for(const f of ['grade','week','day'])if(!Number.isInteger(l[f])||l[f]<(f==='grade'?0:1))errors.push(`${ref}: invalid ${f}`);const map=[l.grade,l.subject,l.week,l.day].join('/');if(mappings.has(map))errors.push(`${ref}: duplicate schedule mapping`);mappings.add(map);if(!l.materials?.length)errors.push(`${ref}: missing materials`);if(!l.phases?.length)errors.push(`${ref}: missing teaching steps`);for(const p of l.phases||[])if(!p.title||!p.actions?.length)errors.push(`${ref}: incomplete phase`);if(l.duration!=null&&(l.phases||[]).reduce((n,p)=>n+(p.minutes||0),0)!==l.duration)errors.push(`${ref}: phase timings do not match duration`);if(!l.assessment?.length)errors.push(`${ref}: missing assessment`);if(!l.source?.status)errors.push(`${ref}: missing source status`);}return errors;}

export function mergeNotes(store,key,changes){let current=store.get(key,{});if(!current||typeof current!=='object'||Array.isArray(current))current={};const data={...current,...changes};return {data,saved:store.set(key,data)};}
